  [52001] = {
    [16001] = {
      character_id = 8,
      event_id = 1,
      probability_type = 1,
      event_name = "Rainfall",
      question_text = "Finally it was closing time. It suddenly started to rain just as you bid your boss goodbye. You decided to...",
      answer_text_1 = "Wait for a while. Maybe it would stop soon.",
      answer_text_2 = "Run for it in the rain.",
      answer_text_3 = "Buy an umbrella somewhere.",
      result_text_1 = "You waited for half an hour but the rain showed no sign of stopping. You saw Shaw walking towards you leisurely holding an umbrella instead.",
      result_text_2 = "Just as you stepped out of the shop, you heard Shaw. ''Don't run. Come here.''",
      result_text_3 = "You met Shaw as you walked out from the convenience store with your newly bought umbrella. He squeezed himself under the umbrella and complained: 'It's too small.'"
    },
    [16002] = {
      character_id = 8,
      event_id = 2,
      probability_type = 1,
      event_name = "Naming Talent",
      question_text = "''Dracona Fly!'' You heard someone saying that behind you, so you...",
      answer_text_1 = "Just ignored it and kept walking.",
      answer_text_2 = "Stopped and turned around.",
      answer_text_3 = "''Someone got the same name, really?!''",
      result_text_1 = "''Hey, you, don't you remember your own name?'' Shaw suddenly appeared from behind, threw his arm around your shoulder, and had you accompany him stroll around the whole day",
      result_text_2 = "Sure enough... You looked at Shaw, speechless. No one else could be so childish.",
      result_text_3 = "You turned back in surprise, startled by Shaw who was suddenly very close. He raised his brows: 'Of course not. I was the one who came up with the name.'"
    },
    [16003] = {
      character_id = 8,
      event_id = 3,
      probability_type = 1,
      event_name = "Afternoon Times",
      question_text = "The antique shop was quiet most of the time. One idle afternoon, you were quietly taking in the precipitation of time, while...",
      answer_text_1 = "Staring at the antiques blankly.",
      answer_text_2 = "Reading books about the Dragonfly Eye.",
      answer_text_3 = "Drawing randomly on paper.",
      result_text_1 = "You fell asleep while staring, and even dreamed that you went to an antique exhibition with Shaw. He mocked your ignorance even in your dream.",
      result_text_2 = "You are overwhelmed by the variety of Dragonfly Eyes in the book and decided to ask Shaw to teach you about them at night.",
      result_text_3 = "You drew a stick figure, then added some shark teeth and a lightning on a second thought."
    },
    [16004] = {
      character_id = 8,
      event_id = 4,
      probability_type = 1,
      event_name = "Antique Market Routine",
      question_text = "The antique market was full of exquisite and novelty gadgets. After choosing for a while, you decided on...",
      answer_text_1 = "Tanghulu Shaped Glass Beads",
      answer_text_2 = "Paper Umbrella with Shadow Play Pattern",
      answer_text_3 = "Mini Draw Bucket of Daily Luck",
      result_text_1 = "The Tanghulu glass beads looked yummy. You heard Shaw's voice just as you were about to buy it: ''Why didn't you just buy a real one if you crave for it?''",
      result_text_2 = "You went home holding the umbrella, not knowing that the pattern was not waterproof... Shaw mocked at you mercilessly.",
      result_text_3 = "Shaw showed up just when you bought it and you drew lots together. He drew good luck while you drew bad luck."
    },
    [16005] = {
      character_id = 8,
      event_id = 5,
      probability_type = 1,
      event_name = "Slight Rest",
      question_text = "You worked hard today and felt tired. You sighed helplessly. So you decided to...",
      answer_text_1 = "Just sleep everything away.",
      answer_text_2 = "Reward yourself to a feast",
      answer_text_3 = "Cheer for yourself",
      result_text_1 = "You fell asleep with your head on the table. Suddenly, someone pulled you by your collar and you heard ''Why can you sleep anywhere?''",
      result_text_2 = "You only realized that you've ordered too much take-outs for yourself after they arrived. To avoid wasting food, you called Shaw and asked if he had eaten yet.",
      result_text_3 = "''Go! Go! Go! Fighting!''After that over-the-top cheering, you heard a snort and hurriedly turned around to explain to Shaw red-faced."
    },
    [16006] = {
      character_id = 8,
      event_id = 6,
      probability_type = 1,
      event_name = "Zither music",
      question_text = "You heard zither music from the end of Westmoon Street. You...",
      answer_text_1 = "Leaned against the window and listened to it with your eyes closed.",
      answer_text_2 = "Followed the sound to check who's there.",
      answer_text_3 = "Hummed the melody to arrange the antiques.",
      result_text_1 = "Someone knocked on the window and interrupted the melody. You frowned and opened your eyes, meeting Shaw's gaze.",
      result_text_2 = "You failed to track the source of the music and stood at the crossroad at a loss when Shaw showed up:''What are you up to?''",
      result_text_3 = "You loved the rhythm and hummed it all day long. Shaw later told you that it's actually composed by their band for the Chinese orchestra."
    },
    [16007] = {
      character_id = 8,
      event_id = 7,
      probability_type = 1,
      event_name = "Strange Visitor",
      question_text = "''Show me the most expensive merchandise in your shop.'' Suddenly the door was pushed opened. You looked up and...",
      answer_text_1 = "Pointed at the most expensive item silently.",
      answer_text_2 = "''Why are you here?!''",
      answer_text_3 = "Put on a professional fake smile.",
      result_text_1 = "Shaw looked at where you're pointing: ''Tsk. The stuffs your shop sells is garbage.''",
      result_text_2 = "Worried that Shaw will be spotted by the boss, you urged him to leave. But he said: ''Nothing to worry about. He can't beat me anyway.''",
      result_text_3 = "''What an 'ugly' smile.'' Shaw looked at you with disdain, then taught you how to wear the perfect fake smile."
    },
    [16008] = {
      character_id = 8,
      event_id = 8,
      probability_type = 1,
      event_name = "Wild Tales",
      question_text = "Wild Tales were popular in the antique market, like how one shouldn't walk on the street alone in the night. You just finished your overtime at midnight...",
      answer_text_1 = "It's all superstition! I won't fall for that!",
      answer_text_2 = "''Maybe I could just spend the night in the shop...''",
      answer_text_3 = "Call Shaw.",
      result_text_1 = "You jumped at a thunder while walking on the street. Shaw walked out from the shadow:''Don't walk alone in the middle of the night if you are so timid.''",
      result_text_2 = "You made a bed on the floor at the warehouse. Shaw showed up just as you were about to close the door,''Let's go.''",
      result_text_3 = "You were mocked by Shaw on the phone but you decided to forgive him as he came to pick you up eventually."
    },
    [16009] = {
      character_id = 8,
      event_id = 9,
      probability_type = 1,
      event_name = "Flashback to Ancient Times",
      question_text = "Perhaps it was because you were at the antique shop all the time that you had been having delusions that if it were the ancient times, you would...",
      answer_text_1 = "Travel around the world unrestrained.",
      answer_text_2 = "Leisurely stay at home.",
      answer_text_3 = "Become an empress.",
      result_text_1 = "''Do you wanna go?'' ''I can let you tag along.'' ''Who's letting whom tag along?''''My apologies. Please let me tag along.''",
      result_text_2 = "''Aren't you already doing that?'' Although you wanted to object, you found that he was actually right.",
      result_text_3 = "''You wish' Shaw commented on how unrealistic your fantasy was."
    },
    [16010] = {
      character_id = 8,
      event_id = 10,
      probability_type = 1,
      event_name = "Fate in Palm",
      question_text = "You were wandering at Westmoon Street when an old lady suddenly stopped you. She asked to tell your fortune by reading your palm.",
      answer_text_1 = "Just play along.",
      answer_text_2 = "''Erm, no thanks.''",
      answer_text_3 = "''I read palms too. How about me reading your palm instead?''",
      result_text_1 = "The old lady said that there's a great disaster hanging over you which can be neutralized by buying a charm. Shaw showed up and caught you by your hand as you were about to pay: ''What disaster? I think she's doing fine.''",
      result_text_2 = "You looked at your palm despite having rejected her offer. Just then, a book titled Collections of All Times was placed on your palm. You looked up indignantly, meeting the big smile on Shaw's face.",
      result_text_3 = "You skillfully read the old lady's palm and she complimented you, when a voice rang: ''Read mine if you are really that good.''"
    }
  },
